with filtered_order_items as (select *, round(quantity, 2) as quantity_rounded from order_items where order_id = 28 and product_id is null), order_items_stats as (select case when quantity_rounded >= 88 then 'high' when quantity_rounded >= 31 then 'mid' else 'low' end as quantity_rounded_bucket, avg(quantity) as avg_quantity from filtered_order_items group by case when quantity_rounded >= 88 then 'high' when quantity_rounded >= 31 then 'mid' else 'low' end) select quantity_rounded_bucket, avg_quantity from order_items_stats order by quantity_rounded_bucket;
